#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <vector>
namespace { constexpr int N=9,Q=24,R=4; void put(std::uint8_t*out,std::size_t p,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(int i=0;i<8;i++)out[p+i]=static_cast<std::uint8_t>(b>>(8*i));} int owned(const bool g[N][N],const int*l,int n,int u,int*out){int z=0;for(int v=0;v<n;v++)if(g[u][v]&&l[u]==0&&l[v]==0)out[z++]=v;return z;} void repair(const bool g[N][N],const int*l,int*m,int n,int u){if(u<0||l[u]!=0||m[u]>=0)return;for(int v=0;v<n;v++)if(g[u][v]&&l[v]==0&&m[v]<0){m[u]=v;m[v]=u;return;}} bool promote(const bool g[N][N],int*l,int*m,int n,int u,const int*tape,int r,int&used){int a[N],count=owned(g,l,n,u,a);if(!count||used>=r||tape[used]>=count)return false;int y=a[tape[used++]],w=m[u],x=m[y];if(w>=0){m[w]=-1;m[u]=-1;}if(x>=0){m[x]=-1;m[y]=-1;}l[u]=l[y]=1;m[u]=y;m[y]=u;if(w>=0)repair(g,l,m,n,w);if(x>=0&&x!=w)repair(g,l,m,n,x);return true;} }
extern "C" std::int64_t two_level_dynamic_maximal_matching_insertions(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap){if(!in||len<3||len>55)return -1;auto n0=in[0],q0=in[1];if((n0!=4&&n0!=9)||q0<0||q0>Q||q0>n0*(n0-1)/2)return -1;int n=int(n0),q=int(q0),u[Q],v[Q];bool seen[N][N]{};std::size_t p=2;for(int i=0;i<q;i++){auto a=in[p++],b=in[p++];if(a<0||b<=a||b>=n0||seen[a][b])return -1;seen[a][b]=true;u[i]=int(a);v[i]=int(b);}if(p>=len)return -1;auto r0=in[p++];if(r0<0||r0>R||len!=p+std::size_t(r0))return -1;int r=int(r0),tape[R];for(int i=0;i<r;i++){auto x=in[p++];if(x<0||x>=n0)return -1;tape[i]=int(x);}bool graph[N][N]{};int level[N]{},mate[N];std::fill(mate,mate+n,-1);int used=0,threshold=n==4?2:3;for(int e=0;e<q;e++){int a=u[e],b=v[e];graph[a][b]=graph[b][a]=true;if(level[a]||level[b])continue;if(mate[a]<0&&mate[b]<0){mate[a]=b;mate[b]=a;}int temp[N],da=owned(graph,level,n,a,temp),db=owned(graph,level,n,b,temp);int who=(da>db||(da==db&&a<b))?a:b;int list[N],d=owned(graph,level,n,who,list);if(d>=threshold&&!promote(graph,level,mate,n,who,tape,r,used))return -1;}if(used!=r)return -1;auto bytes=8*std::size_t(1+2*n);if(!out||cap<bytes)return -2;put(out,0,n);for(int i=0;i<n;i++)put(out,8+8*i,level[i]);for(int i=0;i<n;i++)put(out,8+8*n+8*i,mate[i]);return std::int64_t(bytes);}
